values.content:
Extract structured notes from this meeting.

Meeting: {{ $json.meetingTitle }}
Type: {{ $json.meetingType.replace(/_/g,' ') }}
Date: {{ $json.meetingDate }}
Attendees: {{ $json.attendees.join(', ') || 'not specified' }}
Context: {{ $json.context || 'none provided' }}
Output formats needed: {{ $json.outputFormats.join(', ') }}

Transcript:
{{ $json.transcript }}

Return JSON:
{"summary":"3-5 sentences summarizing what was discussed, decided, and what needs to happen next. Useful to someone who was not in the meeting.","key_topics":["major topics covered"],"decisions":[{"decision":"","rationale":"why this was decided","decided_by":"","effective":"when or under what conditions"}],"action_items":[{"task":"","owner":"","due_date":"specific date or relative like 'by next meeting'","context":"why this action is needed","priority":"high|medium|low"}],"open_questions":[{"question":"","who_needs_to_answer":"","needed_by":""}],"risks_raised":["risks or concerns mentioned in the meeting"],"follow_up_meetings":[{"purpose":"","suggested_attendees":[],"suggested_timing":""}],"email_summary":"a polished 150-word email-ready summary of the meeting — subject line on the first line, then body. Suitable to send to attendees or share with stakeholders who were not there."}
